  if (a === 'U' || b === 'U') return 'U';
  if (a === 'T' && b === 'T') return 'F';
  if (a === 'F' && b === 'F') return 'F';
  return (a === 'T' && b === 'F') || (a === 'F' && b === 'T') ? 'T' : 'F';
}
